{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfa;--muted:#6b6b6b;--accent:#2a7a5f;--warm:#f5efe8;--glass:rgba(255,255,255,0.6);--card:#ffffff}
    *{box-sizing:border-box}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Ubuntu,Helvetica,Arial;line-height:1.4;color:#222;margin:0;background:linear-gradient(180deg,var(--warm),var(--bg));min-height:100vh}
    .wrap{max-width:980px;margin:48px auto;padding:28px}
    nav{display:flex;gap:14px;align-items:center;flex-wrap:wrap}
    nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
    nav a.active,nav a:hover{background:var(--glass);color:#000}
    header.hero{display:grid;grid-template-columns:1fr 320px;gap:22px;align-items:center;margin-bottom:18px}
    .intro{background:linear-gradient(135deg,rgba(255,255,255,0.7),rgba(250,250,250,0.85));padding:26px;border-radius:14px;box-shadow:0 6px 30px rgba(30,30,30,0.06)}
    .intro h1{margin:0;font-weight:600;color:#0f2b22}
    .intro p{margin:10px 0;color:var(--muted)}
    .cta{display:flex;gap:10px;margin-top:14px}
    .btn{background:var(--accent);color:#fff;border:none;padding:10px 14px;border-radius:10px;cursor:pointer}
    .alt{background:transparent;border:1px solid #ddd;padding:10px 12px;border-radius:10px;color:var(--muted)}
    .aside{padding:18px;background:var(--card);border-radius:12px;box-shadow:0 8px 26px rgba(30,30,30,0.04)}
    .aside h3{margin:0 0 8px 0}
    .pill{display:inline-block;font-size:13px;padding:6px 8px;border-radius:999px;background:#eef7f1;color:#0b3b2b}
    section{margin:22px 0;padding:18px;background:var(--card);border-radius:12px}
    .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}
    .service{padding:14px;border-radius:10px;background:linear-gradient(180deg,#fff,#fcfdfc);border:1px solid #f0f0f0}
    .service h4{margin:0 0 8px}
    .meta{color:var(--muted);font-size:13px}
    .micro{display:flex;gap:12px;align-items:center}
    .micro button{padding:10px;border-radius:10px;border:1px solid #eee;background:#fff}

    /* Pricing comparator */
    .pricing-ctrl{display:flex;gap:8px;align-items:center}
    .toggle{background:#f0f0f0;padding:6px;border-radius:999px;display:inline-flex}
    .toggle button{border:0;background:transparent;padding:8px 12px;border-radius:999px;cursor:pointer}
    .toggle button.is-on{background:var(--accent);color:#fff}
    .prices{display:flex;gap:10px;margin-top:12px}
    .price-card{padding:14px;border-radius:10px;background:linear-gradient(180deg,#ffffff,#fcfcfd);min-width:140px;text-align:center;border:1px solid #eee}
    .price-value{font-weight:700;font-size:20px;color:#0b3b2b}
    .small{font-size:13px;color:var(--muted)}
    footer.cta-bar{display:flex;justify-content:space-between;align-items:center;padding:14px;border-radius:10px;background:linear-gradient(180deg,#fff,#fff);margin-top:18px}

    /* Decorative SVG pattern */
    .pattern-svg{position:fixed;right:-80px;top:-80px;width:420px;height:420px;opacity:0.12;pointer-events:none}
    @media(max-width:820px){header.hero{grid-template-columns:1fr}
      .pattern-svg{display:none}}
  </style>
</head>
<body>
  <svg class="pattern-svg" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
    <defs>
      <linearGradient id="g1" x1="0" x2="1">
        <stop offset="0" stop-color="#cbeedc"/>
        <stop offset="1" stop-color="#eaf8f0"/>
      </linearGradient>
      <pattern id="p1" width="20" height="20" patternUnits="userSpaceOnUse" patternTransform="rotate(15)">
        <rect width="10" height="10" fill="url(#g1)" />
        <circle cx="15" cy="5" r="2" fill="#a7dec5" />
      </pattern>
    </defs>
    <rect width="100%" height="100%" fill="url(#p1)" rx="12"/>
  </svg>

  <div class="wrap">
    <nav>
      <a href="index.html">Root</a>
      <a href="services.html" class="active">Offerings</a>
      <a href="conditions.html">Ailments</a>
      <a href="approach.html">Way</a>
      <a href="pricing.html">Rates</a>
      <a href="about.html">Origin</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach</a>
    </nav>

    <header class="hero">
      <div class="intro">
        <h1>Thoughtful care, imagined as a gradual repair.</h1>
        <p>We blend evidence-aware therapies with practical, daily-friendly routines. Choose a pathway that fits your rhythm and the pace you prefer.</p>
        <div class="cta">
          <button class="btn" onclick="location.href='{{PRIMARY_CTA_URL}}'">{{PRIMARY_CTA_LABEL}}</button>
          <button class="alt" onclick="location.href='about.html'">Learn about our tone</button>
        </div>
        <p style="margin-top:12px;color:var(--muted);font-size:13px">Sessions by appointment • Telehealth and in-person in {{CITY}}, {{STATE}}</p>
      </div>

      <aside class="aside">
        <h3>Quick diagnostic</h3>
        <p class="meta">Answer three prompts and get a suggested first step.</p>
        <div style="margin-top:10px;display:flex;gap:8px;flex-direction:column">
          <label class="pill">Time horizon: <select id="diag-horizon" style="margin-left:8px"><option>Short</option><option>Medium</option><option>Long</option></select></label>
          <label class="pill">Energy pattern: <select id="diag-energy" style="margin-left:8px"><option>Up/Down</option><option>Flat</option><option>Frail</option></select></label>
          <button class="btn" id="run-check">Suggest a start</button>
        </div>
        <p id="diag-out" style="margin-top:12px;color:var(--muted);font-size:13px"></p>
      </aside>
    </header>

    <section id="offerings">
      <h3>Paths we steward</h3>
      <p class="meta">Programs designed around seasons of attention: pick a short course, a steady program, or a focused reset.</p>
      <div class="grid" style="margin-top:12px">
        <div class="service">
          <h4>Roots — foundational rhythm</h4>
          <p class="meta">Six-week program emphasizing baseline sleep, breath habits, and simple nutrition rhythm.</p>
          <div style="margin-top:10px"><strong>Includes:</strong>
            <ul style="margin:8px 0 0 18px;padding:0;color:var(--muted)"><li>Weekly 40m session</li><li>Guided micro-practices</li><li>Homework templates</li></ul>
          </div>
        </div>
        <div class="service">
          <h4>Bridge — adaptive coaching</h4>
          <p class="meta">A flexible 12-week track for life changes, combining coaching, gentle modalities, and peer check-ins.</p>
        </div>
        <div class="service">
          <h4>Reset — focused intensive</h4>
          <p class="meta">A short, targeted plan for pressing disruptions: three concentrated visits and daily practices.</p>
        </div>
      </div>
    </section>

    <section id="micro_habits">
      <h3>Small practices that matter</h3>
      <div class="grid">
        <div style="padding:12px;border-radius:10px;background:#fff;border:1px solid #f3f3f3">
          <h4>Breathe & Tally</h4>
          <p class="meta">Two-minute breath pauses with a quick note — anchors attention without burden.</p>
        </div>
        <div style="padding:12px;border-radius:10px;background:#fff;border:1px solid #f3f3f3">
          <h4>Evening Inventory</h4>
          <p class="meta">A single question before bed to close the day and plan one small tomorrow step.</p>
        </div>
      </div>
    </section>

    <section id="pricing">
      <h3>Rates at a glance</h3>
      <p class="meta">Switch the view to see monthly-style billing or one-time package pricing.</p>
      <div class="pricing-ctrl">
        <div class="toggle" role="tablist" aria-label="Pricing toggle">
          <button id="opt-monthly" class="is-on">Monthly</button>
          <button id="opt-package">Package</button>
        </div>
        <div style="margin-left:12px;color:var(--muted);font-size:13px">Animation shows the relative difference</div>
      </div>
      <div class="prices" id="prices">
        <div class="price-card">
          <div class="small">Roots</div>
          <div class="price-value"><span data-price-month="120" data-price-package="650">$120</span><span class="small">/mo</span></div>
          <div class="meta">Weekly touchpoints</div>
        </div>
        <div class="price-card">
          <div class="small">Bridge</div>
          <div class="price-value"><span data-price-month="170" data-price-package="980">$170</span><span class="small">/mo</span></div>
          <div class="meta">Flexible weekly sessions</div>
        </div>
        <div class="price-card">
          <div class="small">Reset</div>
          <div class="price-value"><span data-price-month="340" data-price-package="1190">$340</span><span class="small">/mo</span></div>
          <div class="meta">Focused short plan</div>
        </div>
      </div>
    </section>

    <footer class="cta-bar">
      <div>
        <div style="font-weight:600">Ready for a first step?</div>
        <div style="color:var(--muted);font-size:13px">We’ll suggest a gracious pace and a clear next appointment.</div>
      </div>
      <div style="display:flex;gap:10px;align-items:center">
        <button class="alt" onclick="location.href='contact.html'">Ask a quick question</button>
        <button class="btn" onclick="location.href='{{PRIMARY_CTA_URL}}'">Begin a consultation</button>
      </div>
    </footer>
  </div>

  <script>
    // Diagnostic quick suggestion
    document.getElementById('run-check').addEventListener('click',function(){
      const h = document.getElementById('diag-horizon').value;
      const e = document.getElementById('diag-energy').value;
      const out = document.getElementById('diag-out');
      let note = 'A gentle place to begin: a short rhythm review.';
      if(h==='Short') note = 'Try a Reset: three focused visits with daily anchors.';
      if(h==='Long' && e==='Flat') note = 'Consider Bridge: paced coaching with steady micro-practices.';
      if(e==='Frail') note = 'Start with Roots: foundational sleep and breath work.';
      out.textContent = note;
    });

    // Pricing comparator with animated numbers
    const monthlyBtn = document.getElementById('opt-monthly');
    const packageBtn = document.getElementById('opt-package');
    let mode = 'monthly';
    function animateValue(el, start, end, duration=600){
      const startTime = performance.now();
      function tick(now){
        const t = Math.min(1,(now-startTime)/duration);
        const val = Math.round(start + (end-start)*t);
        el.textContent = '$' + val;
        if(t<1) requestAnimationFrame(tick);
      }
      requestAnimationFrame(tick);
    }
    function updatePrices(targetMode){
      document.querySelectorAll('[data-price-month]').forEach(function(span){
        const month = Number(span.getAttribute('data-price-month'));
        const pack = Number(span.getAttribute('data-price-package'));
        const current = Number(span.textContent.replace(/[^0-9]/g,'')) || (targetMode==='monthly'?pack:month);
        const goal = targetMode==='monthly'?month:pack;
        animateValue(span,current,goal);
        const suffix = targetMode==='monthly'?'/mo':'';
        // update small label after animation
        setTimeout(()=>{
          const parent = span.parentElement; const small = parent.querySelector('.small');
          if(small) small.textContent = suffix;
        },650);
      });
    }
    monthlyBtn.addEventListener('click',function(){ if(mode==='monthly')return; mode='monthly'; monthlyBtn.classList.add('is-on'); packageBtn.classList.remove('is-on'); updatePrices('monthly'); });
    packageBtn.addEventListener('click',function(){ if(mode==='package')return; mode='package'; packageBtn.classList.add('is-on'); monthlyBtn.classList.remove('is-on'); updatePrices('package'); });
  </script>
</body>
</html>"} 
