<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Ailments — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fffdfb;--accent:#4b6b5a;--muted:#666}
    body{font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial;color:#1f1f1f;margin:0;background:var(--bg)}
    .wrap{max-width:920px;margin:40px auto;padding:24px}
    nav{display:flex;gap:12px;flex-wrap:wrap}
    nav a{color:var(--muted);text-decoration:none;padding:6px 8px;border-radius:8px}
    nav a:hover{background:#fff;border:1px solid #eee;color:#000}
    header{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}
    header h1{margin:0;font-weight:600}
    .lead{color:var(--muted);max-width:640px}
    section{margin-top:18px;padding:16px;background:#fff;border-radius:12px;border:1px solid #f2f2f2}
    .grid{display:grid;grid-template-columns:1fr 280px;gap:16px}
    .condition-list{display:grid;gap:12px}
    .cond{padding:12px;border-radius:10px;background:linear-gradient(180deg,#fff,#fbfbfb)}
