    .mood button{padding:8px 10px;border-radius:10px;border:1px solid #eee;background:#fff;cursor:pointer}
    .method{margin-top:12px;padding:12px;border-radius:10px;background:#f8fff7;border:1px solid #e6f2ea}
    .pattern{position:fixed;left:-60px;bottom:-60px;width:360px;height:360px;opacity:0.08;pointer-events:none}
  </style>
</head>
<body>
  <svg class="pattern" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
    <defs>
      <linearGradient id="gg" x1="0" x2="1">
        <stop offset="0" stop-color="#dbeee0"/>
        <stop offset="1" stop-color="#f1fbf6"/>
      </linearGradient>
      <pattern id="p2" width="24" height="24" patternUnits="userSpaceOnUse">
        <rect width="12" height="12" fill="#dff6ea"/>
        <rect x="12" y="12" width="12" height="12" fill="#f1fbf6"/>
        <path d="M0 24 L24 0" stroke="#bfe9d4" stroke-width="1"/>
      </pattern>
    </defs>
    <rect width="100%" height="100%" fill="url(#p2)" rx="14"/>
  </svg>

  <div class="wrap">
    <nav>
      <a href="index.html">Root</a>
      <a href="services.html">Offerings</a>
      <a href="conditions.html" class="active">Ailments</a>
      <a href="approach.html">Way</a>
      <a href="pricing.html">Rates</a>
      <a href="about.html">Origin</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach</a>
    </nav>

    <header>
      <div>
        <h1>Common concerns we support</h1>
        <p class="lead">Educational framing and practical strategies for living with recurring symptoms. We do not promise cures; we provide tools, assessment, and collaborative planning.</p>
      </div>
      <div style="text-align:right">
        <div style="font-size:13px;color:var(--muted)">Contact: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
        <div style="margin-top:8px"><button onclick="location.href='{{PRIMARY_CTA_URL}}'" style="background:#3d6b57;color:#fff;padding:10px 12px;border-radius:10px;border:0;cursor:pointer">Schedule a review</button></div>
      </div>
    </header>

    <section class="grid">
      <div>
        <div class="condition-list">
          <div class="cond">
            <h4>Fatigue and energy fluctuation</h4>
            <p class="meta">We look for sleep pattern influences, metabolic contributors, and pacing strategies. Interventions are educational and paced to your tolerance.</p>
          </div>
          <div class="cond">
            <h4>Digestive irregularities</h4>
            <p class="meta">Dietary patterns, stress response, and gentle lifestyle adaptations can be helpful. We introduce small, testable steps.</p>
          </div>
          <div class="cond">
            <h4>Pain with unclear origin</h4>
            <p class="meta">We emphasize symptom mapping, movement guidance, and nervous system-supportive practices alongside conventional evaluation.</p>
          </div>
        </div>

        <div class="disclaimer">
          Important: Our materials and consultations are educational. We do not offer guaranteed cures or definitive medical diagnoses online. If you have an emergency or sudden severe symptoms, seek urgent care. All plans are developed collaboratively with your input and, when appropriate, coordinated with other clinicians.
        </div>
      </div>

      <aside>
        <h3>Choose how you feel now</h3>
        <p class="meta">Pick a state and we'll suggest a modality and a gentle next step.</p>
        <div class="mood-wrap">
          <button class="mood" data-mood="fog">Fogged</button>
          <button class="mood" data-mood="wired">Wired</button>
          <button class="mood" data-mood="fragile">Fragile</button>
        </div>
        <div class="method" id="method-suggestion">
          <strong>Suggested approach</strong>
          <p style="margin:10px 0;color:var(--muted)">Choose a mood to see a tailored suggestion.</p>
          <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:8px">
            <button onclick="location.href='book.html'" id="mood-cta" style="background:#fff;border:1px solid #e6efe6;padding:8px 10px;border-radius:8px">Book a consult</button>
          </div>
        </div>
      </aside>
    </section>
  </div>

  <script>
    // Mood-to-Method interactive selector
    const mapping = {
      fog: {title:'Gentle structure',note:'Short sleep-and-rhythm adjustments, daily breath anchors, and a single evening inventory. Suggested: Roots program.',cta:'Start a short rhythm plan'},
      wired: {title:'Nervous system settling',note:'Slow somatic practices, paced movement, and brief stimulus reduction. Suggested: Reset or focused visits.',cta:'Request a calming session'},
      fragile: {title:'Very gradual support',note:'Micro-steps, low-demand tasks, and frequent micro-check-ins. Suggested: Bridge with pacing built in.',cta:'Ask about a paced track'}
    };
    document.querySelectorAll('.mood').forEach(btn=>{
      btn.addEventListener('click',()=>{
        const m = btn.getAttribute('data-mood');
        const out = mapping[m];
        const box = document.getElementById('method-suggestion');
        box.querySelector('strong').textContent = out.title;
        box.querySelector('p').textContent = out.note;
        const cta = document.getElementById('mood-cta');
        cta.textContent = out.cta;
        // soft morph: background color pulse
        box.animate([{background:'#f8fff7'},{background:'#fff'}],{duration:450,iterations:1});
      });
    });
  </script>
</body>
</html>"} 
{"path":"approach.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Way — Method & Model — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fcfdfc;--accent:#2d6a50;--muted:#697073}
    body{font-family:Georgia,serif;color:#18211c;margin:0;background:var(--bg)}
    .wrap{max-width:940px;margin:36px auto;padding:24px}
    nav{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:8px}
    nav a{color:var(--muted);text-decoration:none;padding:6px 8px;border-radius:8px}
    nav a:hover{background:#fff}
    .hero{padding:22px;border-radius:12px;background:linear-gradient(180deg,#fff,#fbfffb);border:1px solid #eef6ee}
    .hero h1{margin:0;font-family:inherit}
    .columns{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:16px}
    .card{padding:14px;border-radius:10px;background:#fff;border:1px solid #f2f6f2}
    .steps{display:flex;flex-direction:column;gap:10px}
    .step{padding:12px;border-radius:10px;background:linear-gradient(180deg,#ffffff,#f7fdf6)}
    .mood-row{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}
    .mood-row button{padding:8px 10px;border-radius:8px;border:1px solid #e9efe9;background:#fff;cursor:pointer}
    .method-panel{margin-top:12px;padding:12px;border-radius:10px;background:#f2fbf3;border:1px solid #e2f0e4}
    .pattern-top{position:fixed;right:16px;top:16px;width:220px;height:220px;opacity:0.06;pointer-events:none}
  </style>
</head>
<body>
  <svg class="pattern-top" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
    <defs>
      <pattern id="p3" width="18" height="18" patternUnits="userSpaceOnUse">
        <rect width="9" height="9" fill="#d9f2e4"/>
        <rect x="9" y="9" width="9" height="9" fill="#f0fbf6"/>
        <circle cx="5" cy="13" r="1.6" fill="#bfe5cf" />
      </pattern>
    </defs>
    <rect width="100%" height="100%" fill="url(#p3)" rx="16"/>
  </svg>

  <div class="wrap">
    <nav>
      <a href="index.html">Root</a>
      <a href="services.html">Offerings</a>
      <a href="conditions.html">Ailments</a>
      <a href="approach.html" class="active">Way</a>
      <a href="pricing.html">Rates</a>
      <a href="about.html">Origin</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach</a>
    </nav>

    <div class="hero">
      <h1>How we weave practices and planning</h1>
      <p style="color:var(--muted);margin-top:8px">A few adaptable frameworks we blend: symptom mapping, micro-step experiments, and pacing. Emphasis on testable, compassionate change.</p>
    </div>

    <div class="columns">
      <div>
        <section class="card">
          <h3>Three scaffolds</h3>
          <div class="steps">
            <div class="step"><strong>Map</strong><div style="color:var(--muted);font-size:13px;margin-top:6px">Gather patterns across days: sleep, appetite, mood, and activity.</div></div>
            <div class="step"><strong>Test</strong><div style="color:var(--muted);font-size:13px;margin-top:6px">Introduce one small change for several days and observe. Keep adjustments minimal and measurable.</div></div>
            <div class="step"><strong>Stabilize</strong><div style="color:var(--muted);font-size:13px;margin-top:6px">When a shift helps, shape it into a reliable habit with gentle support.</div></div>
          </div>
        </section>

        <section class="card" style="margin-top:14px">
          <h3>Micro-habits in practice</h3>
          <div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:10px">
            <div style="padding:10px;border-radius:8px;background:#fff;border:1px solid #f2f6f2">Five-minute morning stretch</div>
            <div style="padding:10px;border-radius:8px;background:#fff;border:1px solid #f2f6f2">One-question end-of-day</div>
            <div style="padding:10px;border-radius:8px;background:#fff;border:1px solid #f2f6f2">Three-breath reset</div>
          </div>
        </section>
      </div>

      <aside>
        <div class="card">
          <h3>How do you feel now?</h3>
          <p style="color:var(--muted);font-size:13px">Choose a current state and see the suggested method and CTA text shift.</p>
          <div class="mood-row">
            <button data-key="slow">Slow</button>
            <button data-key="rattled">Rattled</button>
            <button data-key="curious">Curious</button>
          </div>
          <div class="method-panel" id="method-panel">
            <strong id="method-title">Select a state</strong>
            <p id="method-note" style="color:var(--muted);margin-top:8px">Suggestions will appear here. Choices change the invited next step.</p>
            <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:10px">
              <button id="method-cta" style="background:#fff;border:1px solid #eaf4ec;padding:8px 10px;border-radius:8px;cursor:pointer" onclick="location.href='{{PRIMARY_CTA_URL}}'">{{PRIMARY_CTA_LABEL}}</button>
            </div>
          </div>
        </div>

        <div class="card" style="margin-top:12px">
          <h4>Philosophy note</h4>
          <p style="color:var(--muted);font-size:13px">We avoid grand promises. Our role is to teach tools and design small experiments that fit your day.</p>
        </div>
      </aside>
    </div>

    <section style="margin-top:18px;padding:14px;border-radius:12px;background:linear-gradient(180deg,#fff,#fbfff8);border:1px solid #eef6ef">
      <h3>Plan shapes</h3>
      <p style="color:var(--muted)">A short plan is different from a paced track. We name engagements by intent rather than by rigid labels.</p>
      <div style="display:flex;gap:12px;margin-top:10px">
        <div style="padding:12px;border-radius:10px;background:#fff;border:1px solid #eff6ee">Starter Review — single assessment & plan</div>
        <div style="padding:12px;border-radius:10px;background:#fff;border:1px solid #eff6ee">Paced Support — weekly check-ins & adjustments</div>
        <div style="padding:12px;border-radius:10px;background:#fff;border:1px solid #eff6ee">Focused Reset — concentrated sequence for acute disruption</div>
      </div>
    </section>

    <footer style="display:flex;justify-content:space-between;align-items:center;margin-top:18px">
      <div style="color:var(--muted);font-size:13px">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      <div>
        <button onclick="location.href='about.html'" style="background:transparent;border:1px solid #e6efe7;padding:10px;border-radius:10px;margin-right:8px">Our approach</button>
        <button id="primary-action" style="background:var(--accent);color:#fff;padding:10px 12px;border-radius:10px;border:0">{{PRIMARY_CTA_LABEL}}</button>
      </div>
