  </div>

  <script>
    // Mood-to-Method mapping with CTA morph
    const m = {
      slow: {title:'Slow and steady',note:'Very small, low-demand practices: two-minute morning routine, single evening reflection. Suggested: a Starter Review to set a gentle plan.',cta:'Request a Starter Review'},
      rattled: {title:'Soothing resets',note:'Short nervous-system settling tools, paced exposures, and reduced stimulation windows. Suggested: a Focused Reset.',cta:'Book a calming reset'},
      curious: {title:'Experiment mode',note:'Try one micro-test for a week and record results. Suggested: a short paced track for iterative change.',cta:'Try a short experiment'}
    };
    document.querySelectorAll('[data-key]').forEach(btn=>{
      btn.addEventListener('click',()=>{
        const key = btn.getAttribute('data-key');
        const info = m[key];
        document.getElementById('method-title').textContent = info.title;
        document.getElementById('method-note').textContent = info.note;
        const cta = document.getElementById('method-cta');
        cta.textContent = info.cta;
        // also update main primary action label
        document.getElementById('primary-action').textContent = info.cta;
        // subtle motion
        document.getElementById('method-panel').animate([{transform:'translateY(6px)',opacity:0.7},{transform:'translateY(0)',opacity:1}],{duration:360,iterations:1});
      });
    });
  </script>
